async function openDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('fahad-studio',1);q.onupgradeneeded=()=>{q.result.createObjectStore('projects');q.result.createObjectStore('media');};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('قاعدة البيانات مشغولة'));});}
async function saveLocal(revision){if(!db){$('#save-state').textContent='الحفظ التلقائي غير متاح — نزّل نسخة';return;}try{const state=C.clone(p),blobs=[...assets.values()].filter(a=>a.blob).concat(FM.blobs());await new Promise((resolve,reject)=>{const tx=db.transaction(['projects','media'],'readwrite');tx.objectStore('projects').put(state,'current');const store=tx.objectStore('media');for(const id of persistedBlobs.keys())if(!blobs.some(a=>a.id===id))store.delete(id);blobs.forEach(a=>{if(persistedBlobs.get(a.id)!==a.blob)store.put(a.blob,a.id);});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});persistedBlobs=new Map(blobs.map(a=>[a.id,a.blob]));savedRevision=revision;if(revision===saveRevision){$('#save-state').innerHTML='<span class="status-dot"></span> محفوظ على جهازك';dbWarning=false;}}catch(e){$('#save-state').textContent='تعذّر الحفظ التلقائي — نزّل نسخة';if(!dbWarning){toast('مساحة المتصفح غير كافية للحفظ. نزّل المشروع من قائمة «المشروع».','error');dbWarning=true;}}}
async function readLocal(){if(!db)return null;return new Promise((resolve,reject)=>{const tx=db.transaction(['projects','media']);let state,blobs=new Map();const q=tx.objectStore('projects').get('current');q.onsuccess=()=>state=q.result;const keys=tx.objectStore('media').openCursor();keys.onsuccess=()=>{const c=keys.result;if(c){blobs.set(c.key,c.value);c.continue();}};tx.oncomplete=()=>{persistedBlobs=new Map(blobs);resolve(state?{state,blobs}:null);};tx.onerror=()=>reject(tx.error);});}
