async function installProject(state,blobs){C.validate(state);CM.validateAssets(state.assets);FontKit.validateProject(state);dispose();p=C.clone(state);await FM.restore(p.fonts||[],blobs);let missing=0;for(const d of p.assets){if(d.type==='scene'){assets.set(d.id,{...d,thumb:sceneThumb(d.scene,d.colors,d.overlay)});continue;}const blob=blobs.get(d.id);if(!blob){missing++;continue;}const a=await loadAsset(blob,d);assets.set(a.id,a);}if(missing)throw Error('وسائط المشروع مفقودة.');syncAssets();CM.reconcile(p);selected=null;current=0;undo=[];redo=[];canvas.width=p.width;canvas.height=p.height;render();saveSoon();}
