function sceneDraw(cx,scene,t,w,h,colors,overlay=false,options={}){if(X.sceneIds.includes(scene)){X.scene(cx,scene,t,w,h,colors,overlay,options);return;}cx.save();const g=cx.createLinearGradient(0,0,w,h);if(scene==='dunes'){g.addColorStop(0,'#281d37');g.addColorStop(.5,'#86595e');g.addColorStop(1,'#df9f79');}else if(scene==='orbit'){g.addColorStop(0,'#090e25');g.addColorStop(.5,'#272450');g.addColorStop(1,'#2e3c76');}else{g.addColorStop(0,'#0b1635');g.addColorStop(.5,'#25335f');g.addColorStop(1,'#24314b');}cx.fillStyle=g;cx.fillRect(0,0,w,h);
 if(scene==='aurora'){for(let i=0;i<4;i++){const glow=cx.createRadialGradient(w*(.25+i*.18),h*.3,0,w*(.25+i*.18),h*.3,w*.35);glow.addColorStop(0,['#597cef33','#9169ed27','#54d5cb22','#ae66eb25'][i]);glow.addColorStop(1,'#00000000');cx.fillStyle=glow;cx.fillRect(0,0,w,h);}for(let j=0;j<3;j++){cx.beginPath();cx.moveTo(0,h);for(let x=0;x<=w+20;x+=20){const y=h*(.64+j*.10)-Math.sin(x/w*8+j+t*.025)*h*.08-Math.sin(x/w*18+j)*h*.025;cx.lineTo(x,y);}cx.lineTo(w,h);cx.closePath();cx.fillStyle=['#172744','#13223b','#0d1c31'][j];cx.fill();}cx.fillStyle='#d8e0fb';cx.beginPath();cx.arc(w*.75,h*.25,h*.035,0,7);cx.fill();}
 if(scene==='dunes'){cx.fillStyle='#efc6a555';cx.beginPath();cx.arc(w*.73,h*.3,h*.11,0,7);cx.fill();for(let j=0;j<5;j++){cx.beginPath();cx.moveTo(0,h);for(let x=0;x<=w+20;x+=20)cx.lineTo(x,h*(.55+j*.09)+Math.sin(x/w*5+j*1.7+t*.015)*h*.10);cx.lineTo(w,h);cx.closePath();cx.fillStyle=['#996569','#9f6a67','#865359','#654151','#462e44'][j];cx.fill();}}
 if(scene==='orbit'){cx.translate(w*.5,h*.5);cx.rotate(-.35+t*.015);for(let i=0;i<5;i++){cx.beginPath();cx.ellipse(0,0,w*(.13+i*.07),h*(.11+i*.065),0,0,7);cx.strokeStyle=['#b393f270','#827ef05c','#607ccb55','#617cd63a','#9c7cbb28'][i];cx.lineWidth=Math.max(2,w*.003);cx.stroke();}const glow=cx.createRadialGradient(0,0,0,0,0,w*.22);glow.addColorStop(0,'#a17ce933');glow.addColorStop(1,'#a17ce900');cx.fillStyle=glow;cx.fillRect(-w*.3,-h*.4,w*.6,h*.8);cx.fillStyle='#a692ec';cx.beginPath();cx.arc(w*.19,-h*.13,w*.013,0,7);cx.fill();}cx.restore();}
function sceneThumb(scene,colors,overlay=false){const cv=document.createElement('canvas');cv.width=320;cv.height=180;sceneDraw(cv.getContext('2d'),scene,1,320,180,colors,overlay);return cv.toDataURL(overlay?'image/png':'image/jpeg',.7);}
async function loadAsset(blob,known={}){const type=known.type||(blob.type.startsWith('image/')?'image':blob.type.startsWith('audio/')?'audio':blob.type.startsWith('video/')?'video':null);if(!type)throw Error('نوع الملف غير معروف. استخدم فيديو أو صورة أو صوتًا.');const a=CM.restored({...known,id:known.id||C.uid(),name:known.name||blob.name||'وسائط',type,blob,url:URL.createObjectURL(blob)});
 try{if(type==='image'){a.image=await new Promise((resolve,reject)=>{const img=new Image();const timer=setTimeout(()=>reject(Error('انتهت مهلة قراءة الصورة.')),12000);img.onload=()=>{clearTimeout(timer);resolve(img);};img.onerror=()=>{clearTimeout(timer);reject(Error('صيغة الصورة غير مدعومة.'));};img.src=a.url;});a.width=a.image.naturalWidth;a.height=a.image.naturalHeight;a.duration=known.duration||5;const cv=document.createElement('canvas');cv.width=240;cv.height=135;drawFit(cv.getContext('2d'),a.image,240,135,'cover');a.thumb=cv.toDataURL('image/jpeg',.65);}else{const el=document.createElement(type);el.preload='auto';el.playsInline=true;el.muted=true;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('انتهت مهلة قراءة الوسائط.')),18000);el.onloadeddata=()=>{clearTimeout(timer);resolve();};el.onerror=()=>{clearTimeout(timer);reject(Error('تعذّر تشغيل هذا الترميز في المتصفح. جرّب MP4 H.264 أو WebM أو MP3.'));};el.src=a.url;el.load();});a.duration=el.duration;if(!Number.isFinite(a.duration)||a.duration<.1)throw Error('مدة الملف غير صالحة.');a.width=el.videoWidth||0;a.height=el.videoHeight||0;if(type==='video'){const cv=document.createElement('canvas');cv.width=240;cv.height=135;drawFit(cv.getContext('2d'),el,240,135,'cover');a.thumb=cv.toDataURL('image/jpeg',.65);}el.removeAttribute('src');el.load();}return a;}catch(e){URL.revokeObjectURL(a.url);throw e;}}
async function importFiles(files){
 if(exportJob||loading)return;pause();loading=true;const list=[...files],videos=[];let ok=0;remember();
 for(const f of list){
  if(assets.size>=200){toast('الحد الأقصى ٢٠٠ ملف للمشروع.','error');break;}
  if(f.size>200*1048576){toast(f.name+': الحد الأقصى للملف 200 MB.','error');continue;}
  try{toast('جارٍ تجهيز '+f.name);const a=await loadAsset(f,{name:f.name});assets.set(a.id,a);ok++;
   if(a.type==='video'&&autoCaptions){const at=Math.max(0,...p.clips.filter(c=>c.track==='v1').map(c=>c.start+c.duration));const clip=C.clip(a,at);p.clips.push(clip);selected=clip.id;current=clip.start;captionAssetId=a.id;videos.push(a);}
  }catch(e){toast(f.name+' — '+e.message,'error');}
 }
 loading=false;filter='all';panel=videos.length?'captions':'media';changed();
 if(ok)toast(videos.length?'أُضيف الفيديو. تبدأ الكتابة العربية تلقائيًا على جهازك.':'أُضيف '+ok+' من الملفات إلى المكتبة. اضغط + لإدراجها.','success');
 for(const a of videos)queueCaptions(a);pumpCaptions();$('#file-input').value='';
}
function addAsset(id,at,trackId){const a=assets.get(id);if(!a)return;edit(()=>{const want=a.type==='audio'?'audio':'visual',at0=track(activeTrack),tr=trackId||(at0&&at0.kind===want?at0.id:(a.type==='audio'?'a1':'v1'));const last=Math.max(0,...p.clips.filter(c=>c.track===tr).map(c=>c.start+c.duration));const c=C.clip(a,at??last,tr);p.clips.push(c);selected=c.id;current=c.start;});showInspector();}
