function getNode(c){let n=nodes.get(c.id);const a=assets.get(c.assetId);if(n||!a||!['audio','video'].includes(c.kind))return n;const el=document.createElement(c.kind);el.src=a.url;el.preload='auto';el.playsInline=true;el.muted=!audioCtx;el.load();n={el,assetId:c.assetId,ready:false};n.readyPromise=new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('تعذّر تجهيز '+c.name)),18000);el.addEventListener('loadeddata',()=>{clearTimeout(timer);n.ready=true;resolve();},{once:true});el.addEventListener('error',()=>{clearTimeout(timer);reject(Error('تعذّر تشغيل '+c.name));},{once:true});});n.readyPromise.catch(()=>{});nodes.set(c.id,n);if(audioCtx)connectNode(n);return n;}
